UPDATE memberships AS m SET university_id=f.university_id,faculty_id=f.id,faculty=f.name FROM "user" AS u,faculties AS f JOIN universities AS un ON un.id=f.university_id WHERE m.user_id=u.id AND md5(lower(u.email))='24ba4514a80668230e72e37997ebe0c3' AND un.id='demo-university' AND un.name='جامعة قنا الأهلية' AND f.id='demo-computing' AND f.name='كلية الحاسبات والذكاء الاصطناعي' AND f.active=true;
